import{_ as s,o as n,c as t,ag as e}from"./chunks/framework.BFM5MFIQ.js";const h=JSON.parse('{"title":"Синтаксис кубиков","description":"Поддерживаемый синтаксис AnyDice для калькулятора вероятностей.","frontmatter":{"title":"Синтаксис кубиков","description":"Поддерживаемый синтаксис AnyDice для калькулятора вероятностей.","order":10},"headers":[],"relativePath":"ru/reference/dice-probability-syntax.md","filePath":"ru/reference/dice-probability-syntax.md"}'),d={name:"ru/reference/dice-probability-syntax.md"};function p(o,a,l,i,c,r){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="синтаксис-кубиков" tabindex="-1">Синтаксис кубиков <a class="header-anchor" href="#синтаксис-кубиков" aria-label="Permalink to &quot;Синтаксис кубиков&quot;">​</a></h1><p>Поддерживаемый синтаксис калькулятора вероятностей.</p><h2 id="основы-программы" tabindex="-1">Основы программы <a class="header-anchor" href="#основы-программы" aria-label="Permalink to &quot;Основы программы&quot;">​</a></h2><p>Программа состоит из инструкций. Переменные — это слова заглавными буквами, им присваивается значение через двоеточие. <code>output</code> добавляет результат, а <code>named</code> задаёт ему название.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>X: 3</span></span>
<span class="line"><span>output X + 1 named &quot;four&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DAMAGE: 2d6 + 3</span></span>
<span class="line"><span>output DAMAGE named &quot;sword damage&quot;</span></span></code></pre></div><ul><li>Комментарии выделяются обратными слэшами: <code>\\ это игнорируется \\</code></li><li>Переменные можно переприсваивать; они вычисляются по порядку.</li><li><code>0</code> — это ложь; любое другое число — истина.</li><li>В названиях <code>output</code> поддерживается подстановка <code>[ПЕРЕМЕННАЯ]</code>, например <code>named &quot;ability [P]&quot;</code>.</li></ul><h2 id="числа-кубики-и-операторы" tabindex="-1">Числа, кубики и операторы <a class="header-anchor" href="#числа-кубики-и-операторы" aria-label="Permalink to &quot;Числа, кубики и операторы&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Синтаксис</th><th>Значение</th><th>Пример</th></tr></thead><tbody><tr><td><code>+ - * /</code></td><td>Арифметика. Целочисленное деление округляется к нулю.</td><td><code>output 2d6 + 3</code></td></tr><tr><td><code>^</code></td><td>Возведение в степень с неотрицательным целым показателем.</td><td><code>output 2 ^ 3</code></td></tr><tr><td><code>= != &lt; &gt; &lt;= &gt;=</code></td><td>Сравнение. При применении к кубикам даёт кубик из 0 и 1.</td><td><code>output 3d6 &gt;= 15</code></td></tr><tr><td><code>&amp;</code> | <code>!</code></td><td>Логические и, или и не. Ноль — ложь, любое другое число — истина.</td><td><code>output 1d6 &gt; 3 &amp; 1d6 != 6</code></td></tr><tr><td><code>@</code></td><td>Доступ по позиции в последовательности, наборе кубиков или цифрах числа.</td><td><code>output 1@3d6</code></td></tr><tr><td><code>#</code></td><td>Длина последовательности или набора кубиков; количество цифр числа.</td><td><code>output #(3d6)</code></td></tr><tr><td><code>d</code></td><td>Создаёт кубик или набор кубиков.</td><td><code>output 4d6</code></td></tr><tr><td><code>..</code></td><td>Включающий диапазон внутри литерала последовательности.</td><td><code>{1..6}</code></td></tr><tr><td><code>:</code></td><td>Количество повторений и разделитель имени переменной и значения.</td><td><code>{1:4}</code>, <code>X: 3</code></td></tr></tbody></table><p><code>d6</code> — один шестигранный кубик, <code>3d6</code> — набор из трёх кубиков, которые суммируются, <code>d%</code> — это d100. Свои кубики задаются последовательностью, например <code>d{1,2,4,4}</code>. Грани может задавать любое выражение, например <code>2d(1d4)</code>. Пустой кубик записывается как <code>d{}</code>.</p><h2 id="последовательности" tabindex="-1">Последовательности <a class="header-anchor" href="#последовательности" aria-label="Permalink to &quot;Последовательности&quot;">​</a></h2><p>Последовательности записываются в фигурных скобках. Они сохраняют порядок записи; чтобы применить настройку порядка позиций, используйте <code>sort</code>. Математические и логические операции суммируют все элементы последовательности.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{1, 2, 3}</span></span>
<span class="line"><span>{1..6}</span></span>
<span class="line"><span>{1:4, 2, 3}</span></span>
<span class="line"><span>{1..3:2}</span></span>
<span class="line"><span>{{1,2,4}:2, 5, 6}</span></span>
<span class="line"><span>{d6}</span></span>
<span class="line"><span>{}</span></span></code></pre></div><h3 id="позиция-и-длина" tabindex="-1">Позиция и длина <a class="header-anchor" href="#позиция-и-длина" aria-label="Permalink to &quot;Позиция и длина&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 @ {2,4,6}    \\ 2 \\</span></span>
<span class="line"><span>3 @ {2,4,6}    \\ 6 \\</span></span>
<span class="line"><span>{1,3} @ {2,4,6} \\ 8 \\</span></span>
<span class="line"><span># {2,4,6}      \\ 3 \\</span></span>
<span class="line"><span>1 @ 246        \\ 2 \\</span></span>
<span class="line"><span># 1234         \\ 4 \\</span></span>
<span class="line"><span># (3d6)        \\ 3 \\</span></span>
<span class="line"><span>{1,2} @ 3d6</span></span></code></pre></div><p><code>set &quot;position order&quot; to &quot;lowest first&quot;</code> меняет порядок позиций кубиков и цифр. Литералы последовательностей не переупорядочиваются, пока не применён <code>sort</code>.</p><h2 id="циклы-и-условия" tabindex="-1">Циклы и условия <a class="header-anchor" href="#циклы-и-условия" aria-label="Permalink to &quot;Циклы и условия&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loop N over {1..4} {</span></span>
<span class="line"><span>  output Nd4 named &quot;[N]d4&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>X: 1</span></span>
<span class="line"><span>if X = 1 {</span></span>
<span class="line"><span>  output 1</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>else if X = 2 {</span></span>
<span class="line"><span>  output 2</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>else {</span></span>
<span class="line"><span>  output 1d6</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>В условиях можно использовать сравнения и логические операторы. Поддерживается <code>else if</code>. Кубик нельзя напрямую использовать как условие <code>if</code>; передайте его функции с типизированным параметром. Циклы перебирают значения последовательности или кубика.</p><h2 id="функции" tabindex="-1">Функции <a class="header-anchor" href="#функции" aria-label="Permalink to &quot;Функции&quot;">​</a></h2><p>Имена функций состоят из слов строчными буквами и переменных-параметров заглавными. Функция вызывается именем и аргументами в квадратных скобках. Функция завершается при <code>result:</code>; без <code>result</code> она возвращает пустой кубик.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function: add A to B {</span></span>
<span class="line"><span>  result: A + B</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>output [add 1 to 2]</span></span>
<span class="line"><span>output [add d4 to d6]</span></span></code></pre></div><p>Типы параметров определяют преобразование значений. Параметр без типа получает значение без преобразования:</p><ul><li><code>:n</code> — числа. Последовательность суммируется; кубик раскрывается по каждому исходу.</li><li><code>:d</code> — кубики. Число становится постоянным кубиком; последовательность суммируется и становится постоянным кубиком.</li><li><code>:s</code> — последовательности. Число становится последовательностью из одного элемента; кубики раскрываются во все возможные отсортированные броски.</li></ul><p>Функции могут быть рекурсивными. Максимальная глубина задаётся через <code>set &quot;maximum function depth&quot; to N</code>. <code>output</code> и <code>set</code> внутри функции запрещены.</p><h2 id="библиотека-функции" tabindex="-1">Библиотека функций <a class="header-anchor" href="#библиотека-функции" aria-label="Permalink to &quot;Библиотека функций&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Функция</th><th>Значение</th></tr></thead><tbody><tr><td><code>[absolute NUMBER]</code></td><td>Абсолютное значение.</td></tr><tr><td><code>[SEQUENCE contains NUMBER]</code></td><td>1, если число встречается в последовательности, иначе 0.</td></tr><tr><td><code>[count VALUES in SEQUENCE]</code></td><td>Считает вхождения; повторяющиеся значения считаются несколько раз.</td></tr><tr><td><code>[explode DIE]</code></td><td>Продолжает бросок при выпадении максимального значения.</td></tr><tr><td><code>[highest N of DICE]</code></td><td>Сумма N наибольших значений. Поддерживает несколько наборов через <code>and</code>.</td></tr><tr><td><code>[lowest N of DICE]</code></td><td>Сумма N наименьших значений. Поддерживает несколько наборов через <code>and</code>.</td></tr><tr><td><code>[middle N of DICE]</code></td><td>Сумма N средних значений.</td></tr><tr><td><code>[highest of A and B]</code></td><td>Большее из двух чисел; кубики раскрываются по каждому исходу.</td></tr><tr><td><code>[lowest of A and B]</code></td><td>Меньшее из двух чисел; кубики раскрываются по каждому исходу.</td></tr><tr><td><code>[maximum of DIE]</code></td><td>Наибольшее возможное значение кубика (0 для пустого кубика).</td></tr><tr><td><code>[minimum of DIE]</code></td><td>Наименьшее возможное значение кубика (расширение движка).</td></tr><tr><td><code>[reverse SEQUENCE]</code></td><td>Обращает порядок последовательности.</td></tr><tr><td><code>[sort SEQUENCE]</code></td><td>Сортирует с учётом настройки порядка позиций.</td></tr></tbody></table><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set &quot;position order&quot; to &quot;highest first&quot;</span></span>
<span class="line"><span>set &quot;position order&quot; to &quot;lowest first&quot;</span></span>
<span class="line"><span>set &quot;explode depth&quot; to 2</span></span>
<span class="line"><span>set &quot;maximum function depth&quot; to 5</span></span></code></pre></div><p>Настройки применяются к следующим за ними инструкциям. По умолчанию используется порядок от наибольшего к наименьшему.</p><h2 id="примеры" tabindex="-1">Примеры <a class="header-anchor" href="#примеры" aria-label="Permalink to &quot;Примеры&quot;">​</a></h2><h3 id="_4d6-без-худшего" tabindex="-1">4d6 без худшего <a class="header-anchor" href="#_4d6-без-худшего" aria-label="Permalink to &quot;4d6 без худшего&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>output [highest 3 of 4d6] named &quot;4d6 drop lowest&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ABILITIES: 6 d [highest 3 of 4d6]</span></span>
<span class="line"><span>loop P over {1..6} {</span></span>
<span class="line"><span>  output P @ ABILITIES named &quot;Ability [P]&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="blades-in-the-dark" tabindex="-1">Blades in the Dark <a class="header-anchor" href="#blades-in-the-dark" aria-label="Permalink to &quot;Blades in the Dark&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function: blades ROLL:s {</span></span>
<span class="line"><span>  if 1@ROLL = 6 {</span></span>
<span class="line"><span>    result: 2 + (2@ROLL = 6)</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  result: 1@ROLL &gt;= 4</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>output [blades 2d6] named &quot;0d&quot;</span></span>
<span class="line"><span>loop P over {1..7} {</span></span>
<span class="line"><span>  output [blades Pd6] named &quot;[P]d&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="взрывающиеся-кубики" tabindex="-1">Взрывающиеся кубики <a class="header-anchor" href="#взрывающиеся-кубики" aria-label="Permalink to &quot;Взрывающиеся кубики&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set &quot;explode depth&quot; to 3</span></span>
<span class="line"><span>output [explode d6] named &quot;one exploding d6&quot;</span></span>
<span class="line"><span>output 2d[explode d6] named &quot;two independent exploding dice&quot;</span></span></code></pre></div><h3 id="функции-и-приведение-типов" tabindex="-1">Функции и приведение типов <a class="header-anchor" href="#функции-и-приведение-типов" aria-label="Permalink to &quot;Функции и приведение типов&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function: double N:n if above B:n {</span></span>
<span class="line"><span>  if N &gt; B { result: N + N }</span></span>
<span class="line"><span>  result: N</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>output [double d6 if above 3] named &quot;1, 2, 3, 8, 10, 12&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function: ROLL:s count fives and above and subtract ones {</span></span>
<span class="line"><span>  result: (ROLL &gt;= 5) - (ROLL = 1)</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>output [3d6 count fives and above and subtract ones]</span></span></code></pre></div>`,38)])])}const b=s(d,[["render",p]]);export{h as __pageData,b as default};
